/** Sentry Protocol orb firing intervals by module rarity. */

function nonnegativeFinite(value: number, name: string): void {
  if (!Number.isFinite(value) || value < 0) throw new RangeError(`${name} must be finite and nonnegative`)
}

/**
 * Seconds between shots for each stationary workshop orb.
 * Pass the effective orb-speed stat, including its existing modifiers.
 * Zero speed means no shots (Infinity); mini-orb count comes from module rarity.
 */
export function sentryProtocolWorkshopOrbFireInterval(orbSpeed: number): number {
  nonnegativeFinite(orbSpeed, 'orbSpeed')
  return 1 / (5 * orbSpeed)
}

/**
 * Seconds between shots for each Extra Orb card orb.
 * `cardSpeed` is the card's current speed-table value; `extraOrbSpeedLabBonus`
 * is the already-computed additive bonus from research index 14.
 */
export function sentryProtocolCardOrbFireInterval(cardSpeed: number, extraOrbSpeedLabBonus: number): number {
  nonnegativeFinite(cardSpeed, 'cardSpeed')
  nonnegativeFinite(extraOrbSpeedLabBonus, 'extraOrbSpeedLabBonus')
  return 0.5 / (cardSpeed + extraOrbSpeedLabBonus)
}
